@sig trait ShipEvidenceLifecycle_Api {
  def id: Art.BridgeId
  def ship_update_Id : Art.PortId
  def admission_decision_Id : Art.PortId
  def prior_ship_evidence_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var prior_ship_evidence: Mining_Cargo_Transfer_Evidence_Coordinator.ShipEvidenceState.Type = $

  def put_prior_ship_evidence(value : Mining_Cargo_Transfer_Evidence_Coordinator.ShipEvidenceState.Type) : Unit = {
    Contract(
      Modifies(prior_ship_evidence),
      Ensures(
        prior_ship_evidence == value
      )
    )
    Spec {
      prior_ship_evidence = value
    }

    Art.putValue(prior_ship_evidence_Id, Mining_Cargo_Transfer_Evidence_Coordinator.ShipEvidenceState_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ShipEvidenceLifecycle_Initialization_Api (
  val id: Art.BridgeId,
  val ship_update_Id : Art.PortId,
  val admission_decision_Id : Art.PortId,
  val prior_ship_evidence_Id : Art.PortId) extends ShipEvidenceLifecycle_Api

